Here's a JavaScript function that switches the order of adjectives in a sentence:

```javascript
function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectives = [];
  let currentAdjective;

  for (let i = 0; i < words.length; i++) {
    const word = words[i];

    if (word === 'beautiful' || word === 'green') {
      currentAdjective = word;
    } else if (currentAdjective) {
      adjectives.push(currentAdjective);
      currentAdjective = null;
    }
  }

  if (currentAdjective) {
    adjectives.push(currentAdjective);
  }

  const reversedSentence = adjectives.reverse().join(' ') + ' ' + words.filter(word => !['beautiful', 'green'].includes(word)).join(' ');
  return reversedSentence;
}

const sentence = "Beautiful green trees are in the park";
const result = swapAdjectives(sentence);
console.log(result); // Output: Green beautiful trees are in the park
```

