```cpp
class AEADCipher {
public:
    AEADCipher(const std::string& key, const std::string& iv) : key_(key), iv_(iv) {}

    void Encrypt(const std::string& data, std::string& encrypted_data) {
        CryptoPP::AEAD::GCM gcm;
        gcm.SetKey(key_);
        gcm.SetIV(iv_);
        gcm.SetEncryptionMode();
        gcm.Update(data);
        encrypted_data = gcm.Final().ToString();
    }

    void Decrypt(const std::string& encrypted_data, std::string& decrypted_data) {
        CryptoPP::AEAD::GCM gcm;
        gcm.SetKey(key_);
        gcm.SetIV(iv_);
        gcm.SetDecryptionMode();
        gcm.Update(encrypted_data);
        decrypted_data = gcm.Final().ToString();
    }

private:
    std::string key_;
    std::string iv_;
};
