Here's a C++ program that generates the Fibonacci sequence using a recursive function:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    vector<int> sequence;

    // Prompt the user to input the first two integers
    cout << "Enter the first two integers: ";
    getline(cin, input);

    // Parse the input into integers
    istringstream iss(input);
    int a, b;
    iss >> a >> b;

    // Validate the inputs
    if (a < 0 || b < 0) {
        cerr << "Error: Both inputs must be non-negative integers." << endl;
        return 1;
    }

    // Prompt the user to enter the number of sequence elements to generate
    cout << "Enter the number of sequence elements to generate: ";
    cin >> sequence.size();

    // Generate the Fibonacci sequence
    for (int i = 0; i < sequence.size(); i++) {
        sequence[i] = fibonacci(i, a, b);
    }

    // Output the generated sequence
    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

