Here's a simple MATLAB code to identify the tense used in a given sentence:

```MATLAB
function tense = identify_tense(sentence)
    % Define regular expressions for different tenses
    past_simple = '(\w+)(\s*)was(\s*)(\w+)';
    past_continuous = '(\w+)(\s*)were(\s*)(\w+)';
    present_simple = '(\w+)(\s*)is(\s*)(\w+)';
    present_continuous = '(\w+)(\s*)are(\s*)(\w+)';
    future_simple = '(\w+)(\s*)will(\s*)be(\s*)(\w+)';
    future_continuous = '(\w+)(\s*)will(\s*)have(\s*)been(\s*)(\w+)';

    % Check for each tense using regular expressions
    if strfind(sentence, past_simple)
        tense = 'Past Simple';
    elseif strfind(sentence, past_continuous)
        tense = 'Past Continuous';
    elseif strfind(sentence, present_simple)
        tense = 'Present Simple';
    elseif strfind(sentence, present_continuous)
        tense = 'Present Continuous';
    elseif strfind(sentence, future_simple)
        tense = 'Future Simple';
    elseif strfind(sentence, future_continuous)
        tense = 'Future Continuous';
    else
        tense = 'Other';
    end
end

% Test the function with your example sentence
