disp(['The tense of the sentence is: ', result]);
```

This code defines regular expressions for different tenses and checks for each tense using the `strfind` function. If a match is found, the corresponding tense is returned. Otherwise, it returns 'Other'.

Here's an example of a Generic REST Service Wrapper Class in C# that includes Auth Token Handling:

```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;

public class RestServiceWrapper
{
    private readonly string _baseAddress;
    private readonly string _authToken;

    public RestServiceWrapper(string baseAddress, string authToken)
    {
        _baseAddress = baseAddress;
        _authToken = authToken;
    }

    public async Task<T> GetAsync<T>(string endpoint)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);

            var response = await client.GetAsync($"{_baseAddress}/{endpoint}");
            response.EnsureSuccessStatusCode();

            return await response.Content.ReadAsAsync<T>();
        }
    }

    public async Task<T> PostAsync<T>(string endpoint, object data)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);

            var content = new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");

            var response = await client.PostAsync($"{_baseAddress}/{endpoint}", content);
            response.EnsureSuccessStatusCode();

            return await response.Content.ReadAsAsync<T>();
        }
    }
}
```

