```csharp
using UnityEngine;

public class AudioVisualizer : MonoBehaviour {
    public AudioSource audioSource;
    public Visualizer visualizer;

    void Start() {
        audioSource = GetComponent<AudioSource>();
        visualizer = GetComponent<Visualizer>();
        audioSource.Play();
    }

    void Update() {
        visualizer.Update(audioSource.outputData);
    }
}

public class Visualizer {
    public Texture2D texture;
    public int sampleRate;
    public int bufferSize;
    public float amplitudeThreshold;

    void Start() {
        texture = new Texture2D(bufferSize, 1, TextureFormat.RGBA32, false);
        sampleRate = audioSource.outputSampleRate;
        bufferSize = audioSource.outputBufferSize;
        amplitudeThreshold = 0.5f;
    }

    void Update(float[] data) {
        for (int i = 0; i < bufferSize; i++) {
            float amplitude = Mathf.Abs(data[i]);
            if (amplitude > amplitudeThreshold) {
                texture.SetPixel(i, 0, Color.white);
            }

