To create a simple toast notification using React Context, follow these steps:

1. First, let's create a `ToastContext` file to define the context and its provider component.

```javascript
import React, { createContext, useReducer } from 'react';

const ToastContext = createContext();

function ToastProvider(props) {
  const [toasts, dispatch] = useReducer((state, action) => {
    switch (action.type) {
      case 'add':
        return [...state, action.payload];
      case 'remove':
        return state.filter((t) => t.id !== action.payload.id);
      default:
        return state;
    }
  }, []);

  function showToast(message, type = 'info') {
    dispatch({ type: 'add', payload: { message, type } });
  }

  function hideToast(id) {
    dispatch({ type: 'remove', payload: { id } });
  }

  return (
    <ToastContext.Provider value={{ showToast, hideToast }}>
      {props.children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Next, let's create a `Toast` component to display the toast notifications.

