      "js": ["inject.js"]
    }
  ]
}
```
3. In `inject.js`, add the JavaScript code you want to inject into the target webpage. For example:
```javascript
document.addEventListener('DOMContentLoaded', function() {
  console.log('Injected!');
});
```
4. Save both files and refresh your browser with your Chrome extension enabled. The injected JavaScript code should now run on the target webpage.

