Here's a simple example of how you can achieve this using TypeScript, React, and Downshift library:

```typescript
import React, { useState } from 'react';
import { useCombobox } from 'downshift';

const SearchEmails = () => {
  const [emails, setEmails] = useState([]);

  const searchEmails = async (prefix: string) => {
    // Replace this with your actual API call or logic to fetch emails
    const response = await fetch(`https://example.com/api/emails?prefix=${prefix}`);
    const data = await response.json();
    setEmails(data);
  };

  const { isOpen, selectedItem, getMenuProps, getInputProps, getComboboxProps } = useCombobox({
    items: emails,
    getItemKey: (item) => item.email,
    getItemToString: (item) => item.email,
    onSelect: (selectedItem) => console.log('Selected item:', selectedItem),
  });

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} placeholder="Search emails..." />
      <div {...getMenuProps()}>
        {isOpen ? (
          <ul>
            {emails.map((email) => (
              <li key={email.email}>{email.email}</li>
            ))}
          </ul>
        ) : null}
      </div>
    </div>
  );
};

export default SearchEmails;
```

This code uses the `useCombobox` hook from the Downshift library to create an autocomplete input field. The `searchEmails` function is called whenever the user types in the input field, and it fetches emails from an API (in this case, a mock API). The `emails` state is updated with the fetched emails, and the combobox is updated to display the autocompleted suggestions.

