const RemoveWidows = ({ text }) => {
  const [formattedText, setFormattedText] = useState(text);

  const handleRemoveWidows = () => {
    setFormattedText(text.replace(/\n\s+/g, '\n'));
  };

  return (
    <div>
      <p>{formattedText}</p>
      <button onClick={handleRemoveWidows}>Remove Widows</button>
    </div>
  );
};

export default RemoveWidows;
```

